(* [comment removed for export] *)
Lemma KL2_lbrk_pages_ok : forall L pbrk h lo len,
  KL2 L pbrk h ->
  0 < lo -> 0 < len -> lo + len <= alloc_ceiling ->
  region_free (vm_reserved h ++ vm_maps h) (Z_to_bv 64 lo) (Z_to_bv 64 len) = true ->
