  /\ bv_unsigned b + 2 * PGSZ < 2 ^ 64 /\ bv_unsigned (vm_start_brk h) <= bv_unsigned b + 2 * PGSZ /\ req <> 0
  (* [comment removed for export] *)
  /\ (answer_ok L (EBrk req) cur = true /\ KL2 (event_post L (EBrk req) cur) cur h)
